function subjectFromHash(): Subject | null {
  const h = window.location.hash.toLowerCase();
  if (h.startsWith('#/math')) return 'math';
  if (h.startsWith('#/portugues')) return 'portuguese';
  if (h.startsWith('#/estudodomeio')) return 'science';
  if (h.startsWith('#/english') || h.startsWith('#/ingles')) return 'english';
  if (h.startsWith('#/leitor') || h.startsWith('#/lebem')) return 'lebem';
  if (h.startsWith('#/tictactoe') || h.startsWith('#/galo')) return 'tictactoe';
  if (h.startsWith('#/soundhunter')) return 'soundhunter';
  if (h.startsWith('#/familyquiz')) return 'familyquiz';
  if (h.startsWith('#/adventure')) return 'adventure';
  if (h.startsWith('#/missions')) return 'missions';
  if (h.startsWith('#/pixelboard')) return 'pixelboard';
  if (h.startsWith('#/stopgame')) return 'stopgame';
  if (h.startsWith('#/spotit')) return 'spotit';
  if (h.startsWith('#/memory')) return 'memory';
  return null;
}

